bounded_host_request.command:
set -e
cd /home/admin1/projects/webhook-gateway
docker compose exec -T api node - <<'JS'
const x=JSON.parse(process.env.INTERNAL_EVENT_API_PROJECT_KEYS_JSON||'{}');
const k=x['server-core'];
if(typeof k!=='string'||k.length<32)process.exit(4);
const body={
  eventId:'req_52ac76d410b2e8a99fa630c5',
  eventType:'gace.servercore-bounded-host.requested',
  sourceId:'server-core-github',
  destinationId:'server-core-bounded-host',
  subject:'servercore-bounded-host/host.command',
  time:new Date().toISOString(),
  data:{
    schema:'gace.servercore-bounded-host.request/v1',
    id:'req_52ac76d410b2e8a99fa630c5',
    command_id:'host.command',
    expected_sha:'96d01bb845152569658ccd1187b502bf33649c06',
    repository:'seigo-gace/webhook-gateway',
    repo_sha:'e10a0d7606b21c38f0d4f875f7a403cd3d5fe296',
    command:'pwd'
  }
};
(async()=>{
 const response=await fetch('http://127.0.0.1:7373/internal/events',{
   method:'POST',
   headers:{'content-type':'application/json','x-internal-api-token':k},
   body:JSON.stringify(body)
 });
 const result=await response.json();
 console.log(JSON.stringify({event_id:body.eventId,http_status:response.status,accepted:result.ok??false,duplicate:result.duplicate??null,delivery_count:result.deliveries??null,private_value_printed:false}));
 if(response.status!==202||result.ok!==true||result.deliveries!==1)process.exit(2);
})().catch(err=>{console.log('INTERNAL_GATEWAY_REQUEST_ERROR');process.exit(3)});
JS
